// <auto-generated/>
using System.Configuration;
using System.IO;
using System.Text;

/// <summary>
/// Summary description for ReportingServices
/// </summary>

namespace BLL.Report
{
    public class ReportingServices
    {
        public string GetPath
        {
            get { return ConfigurationManager.AppSettings["ReportingServicesFolderPath"]; }
        }

        public string GetPathExportStatement
        {
            get { return ConfigurationManager.AppSettings["ExportStatementFolderPath"]; }
        }

        public string GetFilesDownLoad(string path, bool IsSubFolder)
        {
            var html = new StringBuilder();
            html.Append("<div class=\"main\">");
            html.Append("<div class=\"maincontent\" style=\"padding-top: 0;\">");
            html.Append("<div class=\"contentBox\">");
            html.Append("<table width='400' cellspacing='1px' cellpadding='1px' class='c bg' >");
            html.Append("<tr bgcolor='white' class='report-header'>");
            html.Append("<td align='center'>Click on the link as below to download report excel file</td>");

            string ParentName = "", ParentPath = "";
            int index = path.LastIndexOf(@"\");
            ParentName = path.Substring(index, path.Length - index).Replace(@"\", "");
            ParentPath = path.Substring(0, index);
            string iconFolder = "<img style='border-width:0pt' src='../../App_Themes/Report/Images/folder.gif' />&nbsp;";
            string iconExcel = "<img style='border-width:0pt' src='../../App_Themes/Report/Images/excel.png' />&nbsp;";
            if (path.Contains(GetPath) && path != GetPath)
            {
                html.Append("<tr bgcolor='white'>");
                html.Append("<td align='left' style='padding-left:160px'><a onclick=\"GotoSubFolder('" +
                            ParentPath.Replace(@"\", "^") + "');\">" + iconFolder + "..." + "</a></td>");
                html.Append("</tr>");
            }

            if (Directory.Exists(path))
            {
                string[] Folders = Directory.GetDirectories(path);
                foreach (string folder in Folders)
                {
                    html.Append("<tr bgcolor='white'>");
                    html.Append("<td align='left' style='padding-left:170px'><a onclick=\"GotoSubFolder('" +
                                folder.Replace(@"\", "^") + "');\">" + iconFolder +
                                folder.Substring(path.Length, folder.Length - path.Length).Replace(@"\", "") +
                                "</a></td>");
                    html.Append("</tr>");
                }

                string[] files = Directory.GetFiles(path);

                if (Folders.Length == 0 && files.Length == 0)
                {
                    html.Append("<tr bgcolor='white'>");
                    html.Append("<td align='center'>There is no file or folder</td>");
                    html.Append("</tr>");
                }
                else
                {
                    foreach (string file in files)
                    {
                        index = file.LastIndexOf(@"\");
                        string FileName = file.Substring(index, file.Length - index).Replace(@"\", "");
                        index = file.IndexOf("ReportingServices");
                        int start = file.LastIndexOf("\\Data\\");
                        start += 5;
                        int end = file.Length - start;
                        string PathFile = "";
                        PathFile = file.Substring(start, end).Replace(".xls", "");
                        html.Append("<tr bgcolor='white'>");
                        html.Append("<td align='left' style='padding-left:70px'>" + iconExcel +
                                    "<span class='hand' onclick=\"DownLoadFile('" +
                                    PathFile.Replace("_", "--").Replace("\\", "---") + "');\">" + FileName +
                                    "</span></td>");
                        html.Append("</tr>");
                    }
                }
            }
            html.Append("</tr>");
            html.Append("</table>");
            html.Append("</div>");
            html.Append("</div>");
            html.Append("</div>");
            return html.ToString();
        }
    }
}